<?php $p = $pagination ?? $feed; if ($p['pages'] > 1): $current = $p['page']; $qs = $_GET; unset($qs['r'],$qs['tab']); $pageKey=$page_key??'page'; $suffix=isset($anchor)?'#'.rawurlencode($anchor):''; ?>
<nav class="pagination" aria-label="<?= t('Pagination') ?>"><?php foreach (array_unique([1,max(1,$current-1),$current,min($p['pages'],$current+1),$p['pages']]) as $number): $qs[$pageKey] = $number; ?><a class="<?= $number === $current ? 'active':'' ?>" href="<?= e((isset($tab) ? au($tab,$qs) : url($route ?? 'home',$qs)).$suffix) ?>"><?= $number ?></a><?php endforeach ?></nav><?php endif ?>
